import React, { useState, useRef } from 'react';
import PropTypes from 'prop-types';

const ChunkUpload = (props) => {
    const {
        className,
        style,
        multiple = false
    } = props;

    const [progress, setProgress] = useState(0);
    const [status, setStatus] = useState("idle");
    const fileInputRef = useRef(null);

    const uploadSingleFile = async (
        file,
        uploadedBytesBefore,
        totalBytesAllFiles
    ) => {
        const chunkSize = props.chunk_size || 5 * 1024 * 1024;
        let offset = 0;

        const initRes = await fetch('/file-upload-init', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                filename: file.name,
                component_id: props.id
            })
        });

        const { upload_id } = await initRes.json();

        while (offset < file.size) {
            const chunk = file.slice(offset, offset + chunkSize);
            const formData = new FormData();

            formData.append('upload_id', upload_id);
            formData.append('chunk', chunk);

            await fetch('/upload-chunk', {
                method: 'POST',
                body: formData
            });

            offset += chunkSize;

            // Progress across ALL files
            const completedBytes =
                uploadedBytesBefore + Math.min(offset, file.size);

            const overallProgress =
                completedBytes / totalBytesAllFiles;

            setProgress(overallProgress);

            if (props.setProps) {
                props.setProps({
                    progress: overallProgress
                });
            }
        }

        const completeRes = await fetch('/file-upload-complete', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ 
                upload_id})
        });

        return await completeRes.json();
    };

    const uploadFiles = async (files) => {
        if (!files || files.length === 0) {
            return;
        }

        setStatus("uploading");

        await fetch('/upload-init', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({
                "component_id": props.id
            })
        });

        try {
            const totalBytesAllFiles = Array.from(files).reduce(
                (sum, file) => sum + file.size,
                0
            );

            let uploadedBytesBefore = 0;
            const results = [];

            for (const file of files) {
                const result = await uploadSingleFile(
                    file,
                    uploadedBytesBefore,
                    totalBytesAllFiles
                );

                results.push(result);

                uploadedBytesBefore += file.size;
            }

            setProgress(1);

            if (props.setProps) {
                props.setProps({
                    progress: 1,
                    file_infos: results
                });
            }

            // Reset UI after short delay
            setTimeout(() => {
                setProgress(0);
                setStatus("idle");
            }, 800);
        } catch (err) {
            console.error('Upload error:', err);
            setStatus("idle");
        }
    };

    // Click handler
    const handleClick = () => {
        fileInputRef.current.click();
    };

    // Drop handler
    const handleDrop = (e) => {
        e.preventDefault();

        const files = Array.from(e.dataTransfer.files);

        if (files.length > 0) {
            uploadFiles(files);
        }
    };

    const handleDragOver = (e) => {
        e.preventDefault();
    };

    // UI text logic
    let content;
    if (status === "uploading") {
        content = `Progress: ${(progress * 100).toFixed(1)}%`;
    } else {
        content = (
            <>
                Drag and Drop or <strong>Select File</strong>
            </>
        );
    }

    return (
        <div
            className={`chunked-upload-box ${className || ''}`}
            style={style}
        >
            <div
                className="chunk-upload-box"
                onClick={handleClick}
                onDrop={handleDrop}
                onDragOver={handleDragOver}
            >
                {content}
                {/* Drag and Drop or <strong>Select File(s)</strong> */}
            </div>

            <input
                type="file"
                multiple={multiple}
                ref={fileInputRef}
                style={{ display: 'none' }}
                onChange={(e) => {
                    const files = Array.from(e.target.files);

                    if (files.length > 0) {
                        uploadFiles(files);
                    }
                }}
            />

        </div>
    );
};

ChunkUpload.propTypes = {
    id: PropTypes.string,

    // Single-file compatibility
    // file_info: PropTypes.object,

    // New multi-file output
    file_infos: PropTypes.array,

    progress: PropTypes.number,
    setProps: PropTypes.func,
    chunk_size: PropTypes.number,

    // Enable/disable multi-file uploads
    multiple: PropTypes.bool,

    className: PropTypes.string,
    style: PropTypes.object
};

ChunkUpload.defaultProps = {
    multiple: false,
    file_infos: []
};

export default ChunkUpload;